REPLACE INTO `recipes` (`recipe_id`, `name`, `description`, `date_last_activity`, `uc`, `um`) VALUES
	('65e35de41116a7a22e54b319', 'Pizza Crust-GF', '**Ingredients for 3 medium crusts:**\n\n3 cups almond flour\n\n1 1/2 cups arrowroot powder or tapioca flour\n\n2 1/4 teaspoons baking powder\n\n2 1/4 teaspoons salt\n\n2 1/4 teaspoon oregano\n\n3/8 teaspoon black pepper\n\n4 eggs\n\n3/4 cups milk\n\n**Directions:**\n\n1. Preheat the oven to 425 degrees.\n2. Line a round pizza pan or cookie sheet with parchment paper. (I have 4 pizza pans so I can bake all three at once)\n3. Combine the dry ingredients in a large bowl. Whisk to blend together.\n4. Add eggs and milk to the dry ingredients. Mix well. The batter will be runny—not like typical pizza dough.\n5. Use a spatula to spread the batter evenly onto the pan in a circle shape.\n6. Bake the crust in the preheated oven for 8-12 minutes.\n7. Remove crust from oven and top with sauce and desired toppings. Or freeze the crust for later. Once cooled, place parchment paper between the crusts and they will store perfectly in a ziplock gallon freezer bag until ready to use. I also make sure the size of my circle stays within the range of a gallon bag for this reason.\n8. Bake for another 10-15 minutes with toppings.\n\n‌\n\n**Other Option: Ingredients for 1 large crust:**\n\n2 cups almond flour\n\n1 cup arrowroot powder or tapioca flour\n\n1 1/2 teaspoon. baking powder\n\n1 1/2 teaspoon. salt\n\n1 1/2 teaspoon oregano\n\n1/4 teaspoon black pepper\n\n3 eggs\n\n1/2 cup milk\n\n‌\n\nSource: [https://unrefinedkitchen.com/2012/04/14/pizza-crust-primalpaleo/](https://unrefinedkitchen.com/2012/04/14/pizza-crust-primalpaleo/ "smartCard-inline")', '2025-05-14 10:01:12', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3921854d40cc63485e80f', 'Grain-Free Homestyle Gravy', '### Ingredients\n\n- 3 tbsp butter\n- 3 tbsp navy bean flour or almond flour\n- 2 cups chicken broth (or filtered water)\n- sea salt (to taste)\n- black pepper (to taste)\n\n### Instructions\n\n- Melt butter over low/medium heat and add flour. Stir until the roux becomes just a little golden brown.\n- Add broth/water and simmer until it is almost as thick as you like it. The gravy will continue to thicken as it cools, so remove from heat and add salt and pepper to taste.\n- If you need to thicken it, mix arrowroot and COLD water first. Then add that to the hot gravy.\n\n### Notes\n\n\\*Navy beans ground into a fine flour using a coffee grinder. To make them more digestible I soak huge batches and then dehydrate before grinding.\n\n\\*For pot roast gravy, add the juice from the crockpot as the liquid.\n\nSource: [https://mommypotamus.com/grain-free-homestyle-gravy-thick-creamy/](https://mommypotamus.com/grain-free-homestyle-gravy-thick-creamy/ "smartCard-inline")', '2024-03-02 14:58:51', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e39452587a1979909f4a74', 'Meatballs', '**Serving: 24** **meatballs**\n\n### Ingredients\n\n- 2 pound ground beef\n- 2 large egg\n- 1 onion, minced or onion powder\n- 2 tablespoons tomato paste (can omit)\n- 4 tablespoons dijon mustard\n- 2 tablespoon coconut flour\n- 1 teaspoon celtic sea salt\n- 1 teaspoon ground black pepper\n- 1/2 teaspoon baking soda\n\n### Instructions\n\n- In a large bowl, combine ground beef, egg, and onion\n- Mix in tomato paste, mustard, coconut flour, salt, pepper, and baking soda\n- Use a ¼ cup scoop to form meatballs (about 57 grams each)\n- Place meatballs on a parchment paper lined baking sheet\n- Bake at 350°F for 20-25 minutes, or until instant read thermometer reads 175°F\n- Serve with marinara sauce over spaghetti squash noodles or zucchini noodles\n\nSource: [https://elanaspantry.com/meatballs/](https://elanaspantry.com/meatballs/ "smartCard-inline")', '2025-04-27 21:29:12', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3965c9ad871d336849512', 'Maple-Braised Butternut Squash', '### Ingredients\n\n- 2 lbs butternut squash, peeled and cut into 1” chunks\n- 2 Tbsp [coconut oil](https://www.thepaleomom.com/wiki/coconut-oil/ "‌")\n- ¼ cup [chicken broth](https://www.thepaleomom.com/2012/03/recipe-chicken-bone-broth-revisited.html "‌")\n- ¼ cup [maple syrup](https://www.thepaleomom.com/wiki/maple-syrup/ "‌")\n- [salt](https://www.thepaleomom.com/wiki/himalayan-pink-salt/ "‌"), to taste\n\n### Instructions\n\n1. Heat coconut oil in a large pot over medium-high heat. Once hot, add broth and maple syrup. Add butternut squash and stir to coat.\n2. Cover and reduce heat to low and simmer for 16-20 minutes, until squash is soft and starting to absorb the liquid. Salt to taste.\n\nSource: [https://www.thepaleomom.com/recipe-maple-braised-butternut-squash/](https://www.thepaleomom.com/recipe-maple-braised-butternut-squash/ "smartCard-inline")', '2024-03-21 16:55:51', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e397521ddf77bca5c237fb', 'Beef and Red Bean Chili', 'Ingredients\n\n- 1 tablespoon onion powder\n- 3/8 teaspoon garlic powder\n- 1 tablespoon chili powder OR 1/2 tspn Chipotle seasoning (reduce to half tablespoon)\n- 1 pound ground beef or **1 can of jackfruit**\n- 28 ounces diced tomatoes (or 1 jar diced and 1 jar crushed)\n- 2 boxes of kidney beans, drained and rinsed\n- 2 teaspoons sea salt\n- 1 teaspoon ground pepper (reduce to 3/4 teaspoon)\n- Toppings: avocado, sour cream, grated cheddar cheese\n- Optional: Mix in 1-2 Seasoned Rice packets from Costco\n\nDirections\n\n1. Brown the beef.\n2. Add onion powder, garlic powder, chili powder.\n3. Add tomatoes, beans, salt and pepper.\n4. Bring to a boil and then simmer for 15-20 minutes.\n5. Adjust seasoning with salt and pepper as needed.', '2024-11-04 18:40:08', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3a05c8c1b5970dcacc97d', 'Chili Enchiladas', 'Ingredients\n\n- 1 tablespoon onion powder\n- 3/8 teaspoon garlic powder\n- 1 tablespoon chili powder\n- 2 pounds ground beef\n- 1 can of diced tomatoes\n- 2 boxes of pinto beans, drained and rinsed\n- 2 teaspoons sea salt\n- 1 teaspoon ground pepper\n- Corn tortillas (16 qty)\n\nDirections\n\n1. Brown the beef.\n2. Add onion powder, garlic powder, chili powder.\n3. Add tomatoes, beans, salt and pepper.\n4. Bring to a boil and then simmer for 10 minutes.\n5. Fill tortillas, rolled up and into rectangular dish.\n6. Top with cheese.\n7. Bake at 350 degrees for 20 minutes.', '2024-03-11 17:58:55', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3a1e92948d057fe6ebd6d', 'Potato Stroganoff', 'Ingredients\n\n- 1 pound ground beef, cooked and drained\n- 1 1/2 cups thinly slice potatoes, cooked and drained\n- 1 can coconut milk (entire can)\n- 1 cup milk (replace with water if we don’t have milk)\n- If needed, 1/2 cup water\n- 1 teaspoon onion powder\n- 2 teaspoon garlic powder\n- 2-4 teaspoon salt\n- 1 teaspoon sugar\n- 1 teaspoon black pepper\n- If needed for thickening, 1 tablespoon tapioca. Mixed with a small amount of cold water before adding.\n\nDirections\n\n1. Cook beef separately.\n2. Cook potatoes separately.\n3. To the cooked beef, add the milk and water and all the seasonings.\n4. If needed, add the tapioca thickener at this stage.\n5. Add the cooked sliced potatoes.', '2025-04-27 21:21:14', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3a89d761eefa02d605b06', 'Chicken Alfredo with Brocolli', 'Ingredients\n\n- Cubed chicken, cooked separately\n- Pasta, cooked separately\n- Broccoli florets, cooked separately\n- Cream sauce, cooked separately\n  - 1/2 teaspoon onion powder\n  - 1 teaspoon salt\n  - 1 teaspoon garlic powder\n  - 1/2 teaspoon sugar\n  - 1/2 teaspoon black pepper\n  - 1 can of coconut milk-ONLY the thick part, drain the water\n  - 3-4 teaspoons of tapioca powder added to a very little splash of milk or cold water\n\nDirections\n\n1. Cook the chicken, pasta and broccoli all separately.\n2. Mix the cream sauce ingredients together and bring to a slow boil.\n3. Combine all the ingredients together.', '2025-05-10 18:41:34', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3abc0f8cd991e2ff05bff', 'Paleo Fuddruckers Burger', 'Ingredients:\n\n2 pounds ground beef\n4 teaspoons paprika\n3 teaspoons black pepper\n2 1/2 teaspoons salt\n2 2/3 teaspoon Maple Sugar or Sucanat Sugar\n1/2 teaspoon garlic powder\n1/2 teaspoon onion powder\n1/2 teaspoon cayenne pepper\n\nOptional: Lettuce, mayo, cheese, rotel\n\nDirections:\n\n1. Mix all spices together.\n2. Mix spices by hand tenderly into the meat so it doesn’t get too tough.\n3. Form 12 patties, flat like tortillas but also loosely packed so doesn’t dry out. (about 80 grams per patty)\n4. Preheat the pan on mid heat. Browning both sides of the patties but not cooking all the way through. Those become leftovers to freeze and cooked thoroughly as reheated for future meals.\n5. Thoroughly cook the remaining two patties for dinner that night.\n6. Make your burger with whatever toppings you prefer.', '2024-05-03 19:05:41', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3af887349307288afe8a6', 'Cottage Pie', 'Ingredients\n\n- 2 tablespoons coconut oil\n- 6 cups frozen mixed veggies\n- 3/4 teaspoon sea salt\n- 1/4 teaspoon black pepper\n- 1/2 teaspoon dried thyme\n- 1 pound ground beef or turkey or jackfruit\n\n\nMashed potato ingredients:\n- 3 pounds potatoes, rinsed and cubed\n- 4 tablespoons butter\n- 1 cup milk\n- 1 1/2 cup grated Pecorino Romano cheese\n- 3/4 tablespoon sea salt\n- ground back pepper to taste\n\nDirections\n\n1. Heat the oil in a large skillet over medium heat.\n2. Stir in the salt, pepper and thyme.\n3. Add the veggies and heat until cooked properly.\n4. In another pot, brown the ground meat.\n5. In a third pot, make the mashed potatoes. Add in the butter, milk cheese and salt and pepper after drained and mashed.\n6. Layer all the ingredients into a large dish. Veggies and meat stirred together. Mashed potatoes layered on top.', '2025-04-27 21:20:59', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3c056c8a56a5b0e0d01c6', 'Ranch Style Beans', '### Ingredients\n\n- 1 can pinto beans, drained and rinsed\n- 1/4  can tomato paste\n- 1/4 tablespoon onion powder\n- 1/16 teaspoon garlic powder\n- 1/4 tablespoon chili powder\n- 1/4 teaspoon ground cumin\n- 1/4 teaspoon paprika\n- 1/2 teaspoons salt\n- 1/4 teaspoon packed brown sugar or Sucanat\n- 1/8 teaspoon black pepper\n- Cayenne pepper, optional, for heat, to taste\n\n### Directions\n\n- Combine all the ingredients into a pot.\n- Heat on the stove top.\n- Season with salt and pepper, as needed, to taste.', '2024-03-02 18:23:04', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65e3c8e7ac71d8524a75f183', 'Mac and Cheese', 'Ingredients\n\n- 2 cups water\n- 2 cups milk (or use water if no milk)\n- 2 tablespoons butter\n- 1/2 teaspoon sea salt\n- 1 1/2 cups sharp cheddar cheese, grated\n- 1/2 cup Pecorino cheese, grated\n\nDirections\n\n1. Slowly bring water, milk, butter and salt to a boil\n2. Adjust heat to keep a slow, steady boil, stirring occasionally. Cook pasta one minute longer than indicated with cooking time.\n3. Turn off heat and stir in cheese.', '2024-03-16 17:33:31', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ea455e167fdc301de1f32d', 'Ranch Dressing/Dip', '### INGREDIENTS\n\n- 1/2 cup mayonnaise\n- 1/3 cup full-fat canned coconut milk (shake or stir well before using)\n- ½ teaspoon dried dill\n- ½ teaspoon garlic powder\n- ½ teaspoon onion powder\n- ¼ teaspoon sea salt\n- ¼ teaspoon ground black pepper\n\n### INSTRUCTIONS\n\n1. In a small bowl, combine all ingredients and mix until smooth and creamy.\n2. Chill for at least 30 minutes before serving.\n3. Store in a covered container or mason jar in the refrigerator for up to 1 week.\n\nSource: [https://therealfooddietitians.com/paleo-ranch-dressing-dip/print/9741/](https://therealfooddietitians.com/paleo-ranch-dressing-dip/print/9741/ "smartCard-inline")', '2024-07-04 13:01:06', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ea48c89c856f6ad662250b', 'Beef Taco Bowl', 'Ingredients\n\n- 1 tablespoon onion powder\n- 1 pound ground beef\n- 1 to 1.5 cups kidney beans, cooked or canned\n- 1/2 teaspoon garlic powder\n- 2 teaspoons cumin powder\n- 2 teaspoons sea salt\n- Corn chips to serve this all on top of\n- Optional toppings: tomatoes, cheese\n- 1/2 teaspoon chili powder \n\nDirections\n\n1. Brown the beef.\n2. Add spices.\n3. Add kidney beans.\n4. Serve meat and bean mixter over corn chips. Top with desired toppings.', '2025-04-27 21:24:32', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ea4a816a895d4683c924a6', 'Green Bean Casserole', 'Ingredients\n\n- 2 tablespoons coconut oil\n- 2 tablespoons tapioca flour\n- 1 tablespoon onion powder or 1 onion diced\n- 1 1/2 pounds green beans, ends trimmed and cut into 1-in pieces\n- 1 cup milk\n- 1 cup stock\n- 1 1/2 teaspoon sea salt\n- 1/4 teaspoon black pepper\n\nDirections\n\n1. Melt the coconut oil in a large skillet over medium heat. Once melted, add the tapioca flour and stir until slightly thickened. About 1 minute.\n2. Reduce heat to medium. Add onion and green beans to the pan. Stir until lightly coated.\n3. Pour in stock and coconut milk, while stirring vigorously. It will thicken quickly.\n4. Cook until green beans turn bright green, about 10 minutes.\n5. Pour into a 9x9 inch pan baking for 35-40 minutes.', '2024-03-09 15:35:00', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecd626107d8ab01905f969', 'Honey Roasted Carrots', 'Ingredients\n\n- 1 pound carrots peeled and trimmed\n- 2 tablespoons coconut oil, melted\n- 2 tabelspoons honey\n- salt and pepper to taste\n\nInstructions\n\n1. preheat the over to 400 degrees. Line a sheet pan with parchment paper.\n2. Place carrots in a single layer on the pan.\n3. in a small bowl, mix together the oil, honey, salt and pepper. Pour the honey mixture over the carrots and toss to coat.\n4. Place in the oven and bake for 25-35 minutes, until the carrots are tender and browned. Roasting time may very depending on the size of the carrots.', '2024-03-09 15:38:59', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ece1f0e75f531c7b4dd485', 'Chili Powder', 'Ingredients\n\n- 2 tablespoons paprika\n- 2 teaspoons oregano\n- 1 1/4 teaspoons cumin\n- 1 1/4 teaspoons garlic powder\n- 1 1/4 teaspoons cayenne pepper\n- 3/4 teaspoon onion powder', '2024-03-09 16:26:58', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ece24b7e25ac00221ac8af', 'Spanish Rice', 'Ingredients\n\n- 2 cups white rice\n- 4 cups chicken stock or water\n- 7-8oz tomato paste\n- 1 cup chopped onion\n- 1/2 cup chopped bell pepper\n- 4 cloves diced garlic\n- 1 tablespoon coconut oi\n- 1 teaspoon salt\n\nInstructions\n\n1. In a medium pot, heat oil and sautee onions, bell pepper and garlic until slightly softened.\n2. Add stock/water and tomato paste. Bring to a boil.\n3. Stir in salt and rice. Reduce heat and cook until tender, about 20 minutes.\n4. When rice is ready, taste and add salt if desired.', '2024-03-09 16:31:56', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ece37b52d21abd85f26e02', 'Beef Stew', 'Ingredients\n\n- 2 tablespoon coconut oil\n- 2 pound cubbed beef\n- 1/4 cup coconut flour\n- 2 teaspoon paprika\n- 4 teaspoon salt\n- 1 teaspoon black pepper\n- 1 teaspoon thyme\n- 1 teaspoon oregano\n- 1 teaspoon basil\n- 1 teaspoon rosemary\n- 1 teaspoon garlic powder\n- 1/4 teaspoon crushed red pepper\n- 1 head cauliflower, chopped\n- 4 large carrots, peeled and chopped\n- 2 bell peppers, chopped\n- 1 onion, chopped\n- 3 stalks of celery, chopped\n- 2 potatoes, chopped\n- 4 cups stock, chicken or beef\n- 1 jar whole tomatoes\n- 1 tablespoon arrowroot powder for thickening, if needed\n\nDirections\n\n1. Heat oil in large pot over medium high heat.\n2. Combine coconut flour and spices in a large ziploc bag. And meat to the bag and shake until nicely coated.\n3. Add the seasoned meat to the skillet and brown for 3 minutes. Meat will continue to cook in sauce so browning meat is all you need to do.\n4. Add all vegetables and stir to combine.\n5. Cover and let veggies cook for a few minutes.\n6. Add stock and tomatoes. Stir and bring to a low boil.\n7. Lower heat and let simmer for 10-20. minutes.\n8. Add arrowroot powder to a small amount of cold water. Stir and then add to the stew, stirring to help thicken.', '2025-05-14 09:36:39', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ece67dcbf220432b12ece8', 'King Ranch Chicken', 'Ingredients\n\n- 3 tablespoons butter\n- 1 large onion, chopped\n- 1 large red bell pepper, chopped\n- 2 medium poblano peppers, seeded and chopped\n- 1 jalapeno pepper, seeded and chopped\n- 2 cloves garlic, chopped\n- 1 tablespoon chili powder\n- 1 tablespoon cumin\n- 1 teaspoon sea salt\n- 1 tablespoon coconut flour\n- 1 3/4 cups chicken stock\n- 1 1/2 cups crushed tomatoes\n- 4 ounces diced green chilies\n- 1 1/2 cup sour cream\n- 5 cups cooked, shredded chicken (substitute is jack fruit and white beans)\n- 4 cups cheddar cheese, grated\n- 16 corn tortillas\n\nDirections\n\n1. Preheat oven to 375 degrees. Melt the butter in a large skillet over medium heat. Add the onion and all peppers. Cook for about 8-10 minutes, until softened. Sitr in the garlic, chili powder, cumin, salt and cook for 1 minute.\n2. Sprinkle the coconut flour over the vegetable mixture and cook for 1 minute while stirring continuously. Stir in the stock and bring to a simmer for 4 minutes. Remove from the heat and stir in the tomatoes, chilies and sour cream.\n3. Place the chicken in a large bowl. Pour the vegetable mixture over the top and stir until combined.\n4. Place 8 tortillas on the bottom of a 13x9 dish. Top with half of the chicken mixture and then half of the cheese. Repeat with the remaining ingredients. Bake for 45-50 minutes until cheese is bubbly and the edges of the casserole are just turning golden brown.\n\n‌\n\nSource: Deliciouslyorganic.net', '2024-03-09 17:02:16', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65eceaabc5244b97f6f0e1b3', 'Slow Cooker Refried Beans', 'Ingredients\n\n- 4 cups chopped onion\n- 6 cups dry pinto beans, rinsed and soaked overnight\n- 2 large jalapeno, seed and chopped. Keep some seeds for spice.\n- 7 cloves of chopped garlic\n- 5 teaspoons salt\n- 2 teaspoons black pepper\n- 4 pinches of cumin\n- 8 cups water\n\nDirections\n\n1. To soak beans-rinse and drain. Soak in crock pot on high 30-60 minutes. Turn off pot. Soak 7-24 hours. Drain. Rinse. Then follow below.\n2. Combine all ingredients in the slow cooker.\n3. Cook on high for 8 hours.\n4. Drain excess liquid. Retain it though to add to beans later for desired consistency.\n5. Mash beans with potato masher. Add liquid back as needed.\n6. Freeze portions for later.\n\nSource: 100 Real Days Food', '2024-03-09 17:08:46', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecec7b734766a86f3ebd36', 'Beef Enchiladas', 'For the sauce:\n\n- 3 tablespoons coconut oil\n- 1/2 teaspoons coconut flour\n- 2 tablespoon chili powder\n- 1 teaspoon dried oregano\n- 1 teaspoon ground cumin\n- 2 cups chicken stock\n- 12 ounces tomato paste\n- 1 teaspoon Celtic sea salt\n\n#### For the Filling:\n\n- 1 tablespoon coconut oil\n- 1 large yellow onion, chopped\n- 1 teaspoon ground cumin\n- 2 pounds ground beef\n- 1/2 teaspoon Celtic sea salt\n- 1 can of Pinto beans\n\n#### For the Wraps:\n\n- 1 recipe savory crepes, page 277 of [The Grain-Free Family Table ](https://deliciouslyorganic.net/the-grain-free-family-table/ "‌")or Siete grain-free tortillas (or corn tortillas)\n- 8 ounces raw cheddar, shredded\n\n### INSTRUCTIONS\n\n1. Place the coconut oil and coconut flour in a medium sauce pan over medium heat. Whisk constantly and cook until the coconut flour just turns golden brown, about 2 minutes. Add the chili powder, oregano and cumin and cook, stirring frequently until fragrant, about 30 seconds. Whisk in chicken stock, tomato paste and sea salt. Bring to a simmer over medium-low heat and cook until sauce begins to thicken, about 20 minutes.\n2. Place the coconut oil in a large sauté pan over medium heat. Swirl the pan to coat. Add the onion and cook, stirring frequently, until onion is translucent, about 5 minutes. Make a well in the center of the pan and add the cumin. Cook, stirring constantly until the cumin is fragrant, about 30 seconds. Stir cumin into the onions. Add the ground beef and salt. Cook, breaking up the beef with the back of a wooden spoon until beef is no longer pink.\n3. Preheat oven to 400ºF and adjust the rack to the middle position. Pour half the sauce in the bottom of an 11 x 7-inch baking dish and spread it out evenly. Place a crepe on the counter and top with 1/4 cup of the beef filling. Carefully roll the crepe around the beef and place it in the baking dish. Repeat with the remaining beef and crepes. Pour the remaining sauce on top of the enchiladas and sprinkle with the cheese. Bake for 25 minutes, or until golden brown and bubbly on top. Cool for 10 minutes. Serve.\n\n‌\n\nSource: [https://deliciouslyorganic.net/beef-enchiladas-grain-free-paleo/#tasty-recipes-143604-jump-target](https://deliciouslyorganic.net/beef-enchiladas-grain-free-paleo/#tasty-recipes-143604-jump-target "smartCard-inline")', '2024-03-09 17:19:13', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecee7c5c43ffab28481c30', 'Plantain Fries', 'Ingredients\n\n- 1-2 green plantains (per person)\n- coconut oil\n- salt to taste\n\nDirections\n\n1. Peel the plantains. Slice them in half diagonally cutting them into shape of french fries. Thickness is up to you.\n2. Pour oil in the pan. You want enough to cover the plantains halfway up their sides.\n3. Fry until crispy over medium heat until crispy on the outside and cooked through on the inside.\n4. Strain on paper towel, salt and serve.', '2024-03-09 17:23:44', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecf156ac509dcad1fe0753', 'Easy Roast Chicken', 'Ingredients\n\n- 1 4-lb whole chicken\n- 2 tablespoons coconut oil, melted\n- dash of salt\n- dash black pepper\n- 1/2 cup chicken broth\n\nInstructions\n\n1. Rinse the chicken and pat it dry. Place in baking pan. Drizzle with oil. Sprinkle on salt and pepper.\n2. Add the stock.\n3. Turn oven to 275 degrees and roast the chicken, covered, for about 3 hours.\n4. Increase to 375 degrees roasting for 30-45 minutes/\n5. Remove from the over allowing to rest 5-10 minutes before carving and serving.', '2024-03-09 17:35:28', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecf24d870dd2e15f0c3ca5', 'Herb Gravy', '### Ingredients\n\n- 1 quart Chicken Stock\n- 2 medium onions, coarsely chopped\n- 2 cloves garlic\n- pan drippings from roasted chicken or roasted turkey\n- ½ teaspoon celtic sea salt\n- 1 tablespoon thyme\n\n### Instructions\n\n- In a medium saucepan, heat chicken stock, onions and garlic to a boil\n- Reduce heat and simmer until onions and garlic are soft, about 30 minutes\n- Pour pan drippings into saucepan\n- Blend stock-onion-drippings mixture in a vitamix until smooth\n- Place mixture back in saucepan and reheat, then season with salt and thyme\n- Serve over turkey, Mashed Cauliflower, or anything else\n\n‌\n\nSource: [https://elanaspantry.com/herb-gravy/](https://elanaspantry.com/herb-gravy/ "smartCard-inline")', '2024-03-10 16:48:02', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ecf2a1551551c1fc10207f', 'Oven Fries', 'Ingredients\n\n- 4 russet potatoes, cut in half lengthwise, halves cut into fourths to make 32 wedges\n- 1/4 cup melted coconut oil\n- sea salt\n\nDirections\n\n1. Preheat the oven to 425 degrees. Toss the potatoes with the oil in a large bowl and season generously with salt.\n2. Dump the potatoes out onto a baking sheet, spreading in a single layer.\n3. Roast for 30-35 minutes, shaking the pan every now and then, until the potatoes are cooked through and golden brown.', '2024-03-09 17:39:36', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee08ea1a7846ac72b3c9a0', 'Marinara Sauce', 'Ingredients\n\n- 3 tablespoons evoo\n- 2 cloves garlic\n- 1 tablespoon italian seasoning blend\n- 1 24-ounce jar of whole or crushed tomatoes\n- 1 teaspoon salt\n\nInstructions\n\n1. Place olive oil, garlic and seasoning blend in a cold sauce pan. Turn the heat to medium and heat until garlic starts to sizzle; about 1 minute.\n2. Pour in tomatoes and sea salt. Bring to a low simmer.\n3. Season with additional salt to taste.\n4. Stores in fridge for 5 days or double the recipe and freeze it.', '2024-03-10 14:27:42', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee09c712c116e9f56214da', 'Squash Mac and Cheese', 'Ingredients:\n\n- 1 large spaghetti squash\n- 5 tablespoons butter\n- 1 cup the cream only of coconut milk (can from fridge)\n- 2 teaspoon salt\n- 1/2 teaspoon black pepper\n- 2 cups grated cheddar cheese\n- 1/2 cup grated pecorino romano cheese\n\nInstructions:\n\n1. Preheat the oven to 400 degrees.\n2. Cut spaghettis squash in half and place cut side down in baking dish. Pour water into the dish so that in comes up about 1 inch on the sides of the squash. Bake for 1 hour.\n3. Scoop out seeds and remove flesh.\n4. Preheat over to 350 degrees. Warm butter, coconut milk cream, salt and pepper in a small sauce pan over medium heat. As soon as it begins to lightly simmer, whisk in cheddar cheese until melted. Remove from heat.\n5. Place the squash in a large bowl and pour cheese sauce over top. Toss until combined.\n6. Pour the mixture into a 11x7 dish, spreading evenly with a spatula. Sprinkle on the PR cheese. Bake for 45 minutes until bubbly and golden brown.', '2024-03-10 14:34:03', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee0b619b77b54774c54f49', 'Spaghetti Squash with Chicken and Spinach', 'Ingredients\n\n- 1 large spaghetti squash\n- 3 cups of shredded/cubbed cooked chicken\n- 2 tablespoons coconut oil\n- 8 ounces baby spinach leaves (fresh or frozen)\n- 1 can of coconut milk, cream only\n- 1 1/2 cup crumbled goat cheese\n- 3 teaspoon sea salt\n- Black pepper to taste\n- 1 package of mushrooms, sliced (optional)\n- 1/4 cup chopped walnuts, toasted (optional) [toast on a pan over medium heat for 4-5 minutes until golden brown]\n\nDirections\n\n1. Preheat oven to 400 degrees. Cut squash in half and place cut side down in a large baking dish. Pour water into the dish so it reaches about 1 inch up the sides of the squash. Bake for 1 hour.\n2. Heat oil over medium heat in a large pot. Remove the seeds from the squash, scoop the flesh out and place in the pot. Add spinach leaves, cream and goat cheese. Toss well until goat cheese has melted and the mixture is hot.\n3. stir in the chicken and sea salt and mushrooms if using. Season to taste with black pepper. Top with walnuts, if using.', '2025-04-30 19:10:48', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee10511a7846ac72bd44c3', 'Cheeseburger Spaghetti Squash', 'Ingredients\n\n- 1 spaghetti squash\n- 1 pound ground beef\n- 6-8oz turkey bacon, sliced or chopped\n- 1 cup onion, diced\n- 1/2 teaspoon sea salt\n- 1 teaspoon garlic powder\n- 1/2 teaspoon paprika\n- 1/4 teaspoon black pepper\n- 1 tablespoon coconut oil\n- Shredded cheddar cheese\n- Optional garnishes: shredded lettuce, tomato, nutritional yeast, black olives\n\nDirections\n\n1. Preheat the oven to 375 degrees. Slice squash lengthwise. Remove the seeds and guts and lay cut side down in a dish with water to cover sides up 1 inch. Roast for 43 minutes if put in right when preheat starts not after; until the squash is tender and pulls away intro strands easily.\n2. While the squash cooks, heat a large skillet on medium high.\n3. Cut 6-8 oz of sliced bacon in to cubes. Dice the onions. Mix together dry spices in a small dish.\n4. Melt the coconut oil in the preheated skillet. Add the bacon. Cook for 3-5 minutes.\n5. Add onions and saute with the bacon for 2-3 minutes or until the onions have softened slightly.\n6. Noe the ground beef gets added to the bacon and onion. Mix it well, sprinkle in the spices. Cook until ground beef is done.\n7. Harvest the squash and combine it with the meats. Stir all together.\n8. Top with cheese. Bake for 15 minutes and 375 degrees.\n9. Remove from oven and top with any optional ingredients.', '2024-03-10 15:10:28', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee228db885a5033c35e542', 'Spaghetti Squash Lasagna', 'Ingredients\n\n- 1 pound ground beef\n- 3/4 cup onion, diced\n- 1-2 marina sauce jars\n- coconut oil\n- 1 medium spaghetti squash\n- 2 medium zucchini\n- 8 oz grated cheddar cheese\n- 1/2 teaspoon nutmeg\n- salt and pepper to taste\n\nDirections\n\n1. Preheat oven to 375 degrees to cook squash for 43 minutes putting it in at start of preheat. To prep squash, cut lengthwise and remove string and seeds. Place face down in baking dish with water 1-inch up to the sides.\n2. Brown the ground beef and onions.\n3. Slice zucchini lengthwise into 1/8 inch slices.\n4. Once the spaghetti squash is cooked, shred the inside of the squash with a fork into a strainer. Gently press down on the squash to drain out some of the liquid.\n5. Mix the spaghetti squash with 2/3 of the grated cheese, nutmeg, salt and pepper. Set aside.\n6. In a 13x9 dish, build your lasagne. Zucchini slices on the bottom, spread half of the spaghetti squash mixture, spread half the meat mixture, finish with half of the tomato sauce. Repeat. Finish by adding the remaining zucchini slices (if you have any). Add the remaining cheese.\n7. Bake for 25-30 minutes.', '2024-03-10 17:02:20', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee2b079d6349ae5cd0a4ae', 'Cream of Vegetable Soup', 'Note: For the veggies-can look for a frozen veggie blend to make this easier.\n\nIngredients (these ingredients are all doubled as this freezes well)\n\n- 8 tablespoon butter\n- 4 leeks, roughly chopped\n- 4 carrots, roughly chopped\n- 2 celery stalk, roughly chopped\n- 5 russet potatoes, diced\n- 6 zucchini, cut into 1 inch pieces\n- 8-10 cups chicken stock\n- 2 teaspoon dried thyme\n- 4 teaspoon sea salt\n- 1/2 teaspoon black pepper\n\nDirections\n\n1. Melt butter in the jumbo pot. Add leeks, carrots, celery. Low-medium heat, cover, cook for 20 minutes.\n2. Add potatoes and stock and thyme. Bring to a boil. Simmer for 10 minutes.\n3. Add zucchini. Simmer 15 more minutes. Until zucchini and potatoes are fork tender.\n4. Add salt and pepper.\n5. Using a hand immersion blender, puree the soup. Be careful not to fill the pot too high or this will be very messy.\n6. Season to taste with salt and pepper.', '2024-03-10 17:41:45', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee2de69fd5eb92ee41ba40', 'Zucchini or Eggplant Lasagna', 'Ingredients\n\n- 1 pound ground beef\n- 28 oz jar spaghetti sauce\n- 3 medium zucchini or 1 eggplant, sliced 1/8 inch thick\n- sea salt\n- Cashew Ricotta Cheese (see that recipe card)\n- 16 oz shredded mozzarella cheese\n- 1/4 cup PR cheese\n- 1 large egg\n\nDirections\n\n1. In a medium skillet, brown meat. Drain. Add the marina sauce to the meat. Simmer on low while prepping the next steps.\n2. Slice the zucchini or eggplant into slices. Lightly salt the slices and set aside for 10 minutes. Salting it helps to take out the moisture. After 10 minutes, blot excess moisture with a paper towel.\n3. On a skillet, grill zucchini on each side until cooked, about 1-2 minutes per side. Place on a paper towel to soak any additional moisture.\n4. Preheat oven to 350 degrees.\n5. In medium bowl, mix the cashew ricotta, pr cheese and egg. Stir well.\n6. In a 13x9 dish, spread some sauce on the bottom. Layer the zucchini. Then ricotta mixture. Top with mozzarella. Repeat the process until all ingredients are used up. Top with sauce and mozzarella.\n7. Cover with foil and bake for 30 minutes.', '2024-03-10 17:15:42', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee311a8a1d2726097b8c02', 'Cashew Ricotta Cheese', 'Ingredients\n\n- 1 1/2 cups raw cashews, soaked\n- 1/2 cup water\n- 1 tablespoon nutritional yeast\n- 1 tablespoon of ACV\n- 1/4 teaspoon garlic powder\n- 1/8 teaspoon onion powder\n- sea salt and black pepper to taste\n\nDirections\n\n1. **Soak the cashews for at least two hours in a bowl of water**, covering the cashews in about an inch of water as they will puff up a bit. Drain cashews and place all remaining ingredients into a food processor. Blend until creamy scrapping the sides as needed.\n2. Taste for flavors adding any additional ingredients.\n3. Makes approx 2 cups. Can store in the fridge up to a week.', '2024-03-10 17:21:16', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee3264a37bb8e6adef6ead', 'Cashew Sour Cream Substitute', 'Ingredients\n\n- 1 1/2 cups raw cashews, soaked\n- 1/2 cup water\n- 1 tablespoon nutritional yeast\n- 1 tablespoon of ACV\n\nDirections\n\n1. **Soak the cashews for at least two hours in a bowl of water**, covering the cashews in about an inch of water as they will puff up a bit. Drain cashews and place all remaining ingredients into a food processor. Blend until creamy scrapping the sides as needed.\n2. Makes approx 2 cups. Can store in the fridge up to a week.', '2024-03-10 17:22:05', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee33402e06e43ef6df6ab4', 'Chicken, Spinach and Tomato Soup', 'Ingredients\n\n- 1 tablespoon butter\n- 2 teaspoon garlic powder\n- 2 teaspoon dried italian seasoning\n- 6 cups chicken stock\n- 1 pound chicken thighs\n- 14 ounces diced tomatoes\n- 10 ounces frozen spinach leaves\n- Sea salt\n- PR cheese for sprinkling on top\n\nDirections\n\n1. Melt butter in a large pot over medium heat. Add garlic and italian seasoning. Pour in stock. Bring to a boil.\n2. Add chicken cooking for 12-15 minutes, until chicken is cooked through. Using a pair of tongs, remove the chicken placing on a cutting board.\n3. Add tomatoes and spinach to the soup and cook for 5-10 minutes.\n4. Chop chicken into bite-sized pieces. Season with sea salt.\n5. Ladle into bowls and garnish with PR cheese.', '2024-03-10 17:40:35', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('65ee372e7bb627c87df43ca2', 'Creamy Bean Soup', 'Ingredients\n\n- 1/2 teaspoon garlic powder\n- 3 tablespoon onion powder\n- 1/2 teaspoon chili powder\n- 1/2 teaspoon cumin\n- 1 teaspoon thyme\n- 4 cups white beans\n- 4 cups kidney beans\n- 4 cups pinto beans\n- 4 cups chicken broth\n- cheddar cheese\n- salt and pepper to taste\n- Cayenne pepper to taste\n\nDirections\n\n1. In a large pot, add beans and broth and spices. Boil. Simmer, covered, 10 minutes.\n2. Blend with immersion blender.\n3. Serve with cheese on top.', '2024-03-10 17:46:25', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('660094acc92698bb05e09a01', 'Burger Bun', '', '2024-03-24 16:07:53', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('66804801d104693530f1c13c', 'Nugget quick lunch', 'Don\'t put nuggets in until preheat is done \nPlace parchment paper or equivalent in oven\nPreheat 425\nLay 4-6 nuggets in oven \nSet time for 16 minutes\nFlip nuggets over\nSet timer for another 6-7 minutes (check periodically for preferred brownness)\n\nIf you want veggie, we have mixed veggies, green beans, and broccoli. 1/2 to 1 C covered with water. Bring to boil, reduce heat to light boil for 3-4 minutes (broccoli may need an additional min or two)', '2024-06-29 12:44:39', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('66b7c3184068f33b52b99099', 'Spaghetti Squash', 'Directions\n\n1. Slice squash length wise and remove seeds.\n2. Add each half flat side down in baking dish.\n3. Add water to dish to cover a inch at least of the squash.\n4. Bake 375 degrees for 43 minutes.\n5. After baked, use a fork to scrap it all into a dish. Add salt. Large squash needs 2.5 teaspoon salt.\n6. Can also use this as a dish with chicken, spinach and goat cheese.', '2024-08-10 14:56:31', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('66b7c63aef984308441f4e1c', 'Salmon Patties', 'Ingredients\n\n- 2 cans of salmon makes 14 patties\n- 3 eggs\n- about 2.5 cups of almond flour\n- Coconut oil for pan\n\nDirections\n\n1. Add salmon and eggs to a bowl and mix.\n2. Make 14 patties at 70 grams each\n3. Something here with the flour\n4. ‌\n5. Stove at 4.5', '2025-04-28 17:29:26', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('674d02a9d61c5c455626f834', 'Mac and cheese for one meal', 'This recipe can also be used if you just want the cheese sauce\n\n1 cup of pasta \n1 tbsp of butter \n1/4 teaspoon of salt \nShredded cheddar cheese based on desired consistency \nAbout an eighth of a cup of water\n', '2024-12-01 18:44:50', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67e09ccb91874e7d03e8bac7', 'Chicken a la King', 'Ingredients\n\n- 1 large spaghetti squash\n- 3 cups of shredded/cubbed cooked chicken\n- 1 can of coconut milk, cream only\n- 1 1/2 cup crumbled goat cheese\n- 3 teaspoon sea salt\n- 1tsp Black pepper\n- 1/4 cup sunflower seeds, toasted (optional)\n- 1 Cup pasta per serving \n\nDirections\n\n1. Preheat oven to 400 degrees. Cut squash in half and place cut side down in a large baking dish. Pour water into the dish so it reaches about 1 inch up the sides of the squash. Bake for 1 hour.\n2. stir in the chicken and sea salt and mushrooms if using. Season to taste with black pepper. Top with sunflower seeds, if using.\n3. Each serving can be done with a cup of penne pasta.', '2025-03-23 18:47:00', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f2cfc24e06ecf0c14db8d8', 'Taco seasoning', '1 tbsp chili powder \n1 tsp ground cumin\n1 tsp paprika \n1 tsp garlic powder \n1 tsp onion powder \n1/2 teaspoon oregano \n1/2 teaspoon salt \n1/2 teaspoon black pepper \n\nUse this combination per pound of ground meat. Add 1 tablespoon of water to the meat and spices. Drain the meat before adding the seasoning and water\n\n\n\n\n', '2025-04-13 07:03:32', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6c4722785635c12d6bfef', 'Black Bean Tacos', '**Ingredients:**\n\n- 1 can black beans (drained + rinsed)\n- 1 tsp cumin\n- 1/2 tsp chili powder\n- Salt + pepper to taste\n- Corn or flour tortillas\n  **Optional toppings:** diced tomato, avocado, cheese\n\n**How-to:**\n\n1. Heat a skillet, toss in black beans + spices, stir until warm and a little thickened.\n2. Warm tortillas.\n3. Spoon beans onto tortillas and pile on your toppings.', '2025-04-09 14:03:49', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d1a82f24c4e9aa7fd634', 'One Pot Black Bean and Rice Skillet', '**Ingredients:**\n\n- 1 can black beans (drained)\n- 1 cup rice (white or brown)\n- 1 can diced tomatoes (with juice)\n- 1 bell pepper, chopped\n- 1/2 onion, chopped\n- 2 cups veggie or chicken broth\n- 1 tsp cumin + 1/2 tsp smoked paprika (optional: chili powder, garlic)\n- Salt & pepper\n- Optional toppings: cheese, avocado, green onion, hot sauce\n\n**How-to:**\n\n1. Sauté onion + pepper in a bit of oil until soft.\n2. Add spices, stir for a minute.\n3. Add rice, beans, tomatoes, and broth.\n4. Bring to a boil, then reduce to low, cover, and simmer until rice is cooked (about 20 min for white, 35-40 for brown).\n5. Fluff and top as you like!', '2025-04-09 15:00:02', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d1f2c9c94bac53e7a203', 'Black Bean Sweet Potato Chili', '**Ingredients:**\n\n- 1 can black beans\n- 1 large sweet potato, cubed\n- 1 can diced tomatoes\n- 1/2 onion, chopped\n- 2 cups veggie broth\n- 1 tsp cumin, 1/2 tsp smoked paprika, 1/4 tsp cinnamon (optional but amazing)\n- Salt, pepper\n\n**How-to:**\n\n1. Sauté onion until soft.\n2. Add sweet potato, beans, tomatoes, broth, and spices.\n3. Simmer until sweet potato is fork-tender (20–25 min).\n4. Taste, season, and top with avocado or a swirl of yogurt.', '2025-04-09 15:01:07', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d2beff0244014051ceb1', 'Creamy Coconut Black Beans and Rice', '**Ingredients:**\n\n- 1 can black beans\n- 1 cup rice\n- 1 can coconut milk (full-fat or light)\n- 1 cup water or broth\n- 1/2 tsp garlic powder, 1/2 tsp ginger powder\n- Salt to taste\n- Optional: lime, cilantro, chili flakes\n\n**How-to:**\n\n1. Dump it all in a pot.\n2. Bring to boil, then simmer covered 18–20 min until rice is done.\n3. Stir, taste, and finish with lime juice or chili flakes if you want a little kick.', '2025-04-09 15:04:22', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d3181ecadb49da60fcbf', 'Tuscan-Style Cannellini Bean Stew', '**Ingredients:**\n\n- 2 cans cannellini beans (drained)\n- 3 cloves garlic, minced (or 1 tsp garlic powder)\n- 1 can diced tomatoes\n- 2 cups veggie or chicken broth\n- 1 tsp dried rosemary or thyme\n- Olive oil\n- Salt, pepper, pinch of chili flakes\n- Optional: handful of chopped kale or spinach, squeeze of lemon\n\n**How-to:**\n\n1. Sauté garlic in olive oil until fragrant.\n2. Add tomatoes, beans, broth, herbs, and seasonings.\n3. Simmer 15–20 minutes until thickened and cozy.\n4. Add greens at the end if using, and finish with lemon juice for brightness.', '2025-04-09 15:26:27', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d365cbfc9cd17164d86a', 'Warm Cannellini Bean Pasta (Tuscan-Style Skillet)', 'Creamy without cream, and full of flavor.\n\n**Ingredients:**\n\n- 1/2 lb pasta (short shapes like orecchiette, penne, or shells)\n- 2 cans cannellini beans (drained + rinsed)\n- 3 cloves garlic (minced or sliced)\n- 1 tbsp olive oil\n- 1 tsp rosemary or thyme (dried or fresh)\n- 1/2 cup veggie or chicken broth (or pasta water)\n- Salt, pepper, chili flakes to taste\n- Optional: squeeze of lemon, grated Parmesan, or a handful of spinach\n\n**How-to:**\n\n1. Cook pasta in salted water until al dente. Save about 1/2 cup pasta water.\n2. While pasta cooks, heat olive oil in a skillet over medium heat.\n3. Add garlic and herbs. Sauté until garlic is fragrant.\n4. Add cannellini beans and broth (or pasta water). Simmer 5–7 min until beans start to break down a bit and sauce thickens.\n5. Stir in cooked pasta. Toss to coat and warm through.\n6. Add lemon juice or Parmesan if using, and adjust seasoning.', '2025-04-09 15:26:25', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d7a90dfe222116694fa7', 'Black Bean & Ground Chicken Skillet', '**Type:** One-pan\n**Vibe:** Weeknight protein bomb\n**Ingredients:**\n\n- 1 lb ground chicken\n- 1 can black beans\n- 1/2 cup tomato sauce\n- 1/2 tsp garlic powder\n- 1/2 tsp onion powder\n- 1 tsp smoked paprika\n- Salt, pepper\n- Optional: cooked rice or GF pasta to serve over\n\n**How-to:**\nBrown chicken with spices, add tomato sauce + black beans, simmer 5–10 min. Serve over rice or pasta. Add cheese if you want.', '2025-04-09 15:25:31', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d7e733d4ebefa32d1be1', 'Black Bean Coconut Soup', '**Type:** Soup\n**Vibe:** Creamy + slightly smoky\n**Ingredients:**\n\n- 1 can black beans\n- 1/2 can coconut milk\n- 1 cup broth\n- 1/2 tsp garlic powder\n- 1/2 tsp onion powder\n- 1/2 tsp cumin\n- Optional: chili flakes, chopped spinach\n\n**How-to:**\nSimmer everything 15 minutes. Blend half (optional) for a creamier texture. Garnish with a swirl of coconut milk or cheese.', '2025-04-09 15:26:19', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d814dd2e1cc72fa318bd', 'Baked Black Bean Pasta (creamy or cheesy)', '**Type:** Bake\n**Vibe:** Cozy comfort\n**Ingredients:**\n\n- Cooked gluten-free pasta\n- 1 can black beans\n- 1/2 can coconut milk **or** 1/2 cup tomato sauce\n- Spices: garlic & onion powder, cumin, smoked paprika\n- Optional: shredded cheddar cheese for top\n\n**How-to:**\nMix cooked pasta, beans, sauce of choice, and seasonings. Pour into dish. Top with cheese if using. Bake at 375°F for 20 min.', '2025-04-09 15:27:11', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d83b8b90154cd16b9174', 'Jackfruit and Black Bean Chili', '**Type:** One-pot\n**Vibe:** Meaty vegan stew\n**Ingredients:**\n\n- 1 can jackfruit (shredded with hands or fork)\n- 1 can black beans\n- 1 can diced tomatoes\n- 1/2 tsp each: garlic powder, onion powder, cumin, chili powder\n- Salt, pepper\n\n**How-to:**\nSauté jackfruit with spices, add tomatoes + black beans. Simmer 20–30 min until thick. Great with rice or GF cornbread.', '2025-04-09 15:27:46', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d86e51c3735b50f5af4e', 'Black Bean and Beef Enchilada Bake', '**Type:** Casserole\n**Vibe:** Cheesy & hearty\n**Ingredients:**\n\n- 1/2 lb ground beef\n- 1 can black beans\n- 1/2 cup tomato sauce\n- Spices: garlic/onion powder, cumin, chili powder\n- Cooked GF pasta or rice\n- Optional: shredded cheddar cheese\n\n**How-to:**\nBrown beef with spices. Mix with beans, sauce, and pasta or rice. Spread in baking dish, top with cheese, bake 15–20 min.', '2025-04-09 15:28:38', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d89c820310bb4d5b7dfe', 'Creamy Cannellini Bean & Herb Soup', '**Type:** Soup\n**Vibe:** Cozy, Italian-inspired\n**Ingredients:**\n\n- 2 cans cannellini beans\n- 1/2 cup coconut milk\n- 1 cup broth\n- 1/2 tsp garlic powder\n- 1/2 tsp onion powder\n- 1 tsp dried rosemary or thyme\n- Optional: cooked chopped spinach or kale\n\n**How-to:**\nBlend one can of beans with broth + coconut milk. Simmer with second can and seasonings for 15–20 minutes. Add greens last if using.', '2025-04-09 15:29:30', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d8d2bf3d8478b9410442', 'Creamy Cannellini Bean Pasta Bake', '**Type:** Casserole/Bake\n**Vibe:** Dairy-free Alfredo-ish\n**Ingredients:**\n\n- Cooked GF pasta\n- 1 can cannellini beans\n- 1/2 cup coconut milk\n- 1 tsp garlic powder\n- 1/2 tsp onion powder\n- Optional: smoked paprika or Italian herbs\n- Optional: shredded cheddar on top\n\n**How-to:**\nBlend beans, coconut milk, and seasonings. Mix with pasta, pour into baking dish, top with cheese (if using), bake at 375°F for 20 min.', '2025-04-09 15:30:17', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
	('67f6d8ed0ba832c5d59c9c5b', 'Cannellini Bean & Ground Chicken Skillet', '**Type:** One-pan\n**Vibe:** Protein-rich and filling\n**Ingredients:**\n\n- 1 lb ground chicken\n- 1 can cannellini beans\n- 1/2 cup tomato sauce\n- Garlic/onion powder, oregano, salt, pepper\n\n**How-to:**\nBrown chicken with spices, stir in beans + sauce, simmer 10 minutes. Serve as-is or over rice.', '2025-04-28 21:45:22', '2025-08-11 15:30:16', '2025-08-11 10:30:16'),
